// Frame — Gtk.Frame
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles frame with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface FrameProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.Frame */
  child?: ReactNode

  /** utf8, from Gtk.Frame */
  label?: string

  /** Widget, from Gtk.Frame */
  labelWidget?: ReactNode

  /** gfloat, from Gtk.Frame */
  labelXalign?: number
}

export function Frame({ className, children, label }: FrameProps) {
  return (
    <div className={cn("rounded-[12px]", className)}>
      {label}
      {children}
    </div>
  )
}
